SELECT *
FROM acc_project_deliverable_source_version
WHERE tenant_id = #{query.tenantId}
  AND deliverable_id = #{query.deliverableId}
  AND source_object_type = 'AcceptanceReportVersion'
  AND source_object_id = #{query.sourceObjectId}
  AND source_version = #{query.sourceVersion}
  AND deleted = b'0'
FOR UPDATE

SELECT *
FROM acc_project_deliverable_source_version
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.sourceVersionId}
  AND deleted = b'0'
FOR UPDATE

